11	// graphFromJSON parses a graph document, failing the test on error.
12	func graphFromJSON(t *testing.T, data string) map[string]*Lineage {
13		t.Helper()
14		graph, err := UnmarshalGraphFile([]byte(data))
15		if err != nil {
16			t.Fatalf("UnmarshalGraphFile(%q): %v", data, err)
17		}
18		return graph
19	}
20	
21	func snapshotOf(t *testing.T, graphJSON string) *SnapshotFile {
22		t.Helper()
23		snap, err := BuildSnapshot(graphFromJSON(t, graphJSON))
24		if err != nil {
25			t.Fatalf("BuildSnapshot: %v", err)
26		}
27		return snap
28	}
29	
30	// TestSnapshotDeterministicBytes is the core content-addressing guarantee:
31	// record order, upstream order, duplicate upstreams, and JSON whitespace must
32	// not influence either the content identifier or the serialized snapshot
33	// bytes, as long as the graph semantics are equal.
34	func TestSnapshotDeterministicBytes(t *testing.T) {
35		inputs := []string{
36			`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","A"]},{"name":"C","upstreams":["B","A"]}]}`,
37			`{ "datasets": [ {"upstreams": ["A","B","A"],"name":"C"}, {"upstreams":[],"name":"A"}, {"name":"B","upstreams":["A"]} ] }`,
38			"{\"datasets\":[\n  {\"name\":\"C\",\"upstreams\":[\"B\",\"A\"]},\n  {\"name\":\"A\",\"upstreams\":[]},\n  {\"name\":\"B\",\"upstreams\":[\"A\"]}\n]}\n",
39		}
40		var wantID string
41		var wantBytes []byte
42		for i, in := range inputs {
43			snap := snapshotOf(t, in)
44			got, err := MarshalSnapshot(snap)
45			if err != nil {
46				t.Fatalf("MarshalSnapshot input %d: %v", i, err)
47			}
48			if i == 0 {
49				wantID = snap.ContentID
50				wantBytes = got
51				continue
52			}
53			if snap.ContentID != wantID {
54				t.Errorf("input %d content id = %s, want %s", i, snap.ContentID, wantID)
55			}
56			if string(got) != string(wantBytes) {
57				t.Errorf("input %d snapshot bytes differ:\n got %s\nwant %s", i, got, wantBytes)
58			}
59		}
