162		tampered.ContentID = good.ContentID + "deadbeef"
163		tb, err := MarshalSnapshot(&tampered)
164		if err != nil {
165			t.Fatalf("marshal tampered: %v", err)
166		}
167		if _, err := ParseSnapshot(tb); !errors.Is(err, ErrInvalidArgument) {
