347			t.Errorf("RemovedRelations = %v, want %v", report.RemovedRelations, wantRemoved)
348		}
349		wantRootChanges := []RootSourceChange{
350			{Dataset: "B", OldRoots: []string{"A"}, NewRoots: []string{"X"}},
351			{Dataset: "C", OldRoots: []string{"A"}, NewRoots: []string{"X"}},
352		}
353		if !reflect.DeepEqual(report.RootSourceChanges, wantRootChanges) {
354			t.Errorf("RootSourceChanges = %v\nwant %v", report.RootSourceChanges, wantRootChanges)
