512		oldSnap := snapshotOf(t, `{"datasets":[{"name":" Raw ","upstreams":[]},{"name":"RAW","upstreams":[" Raw "]}]}`)
513		newSnap := snapshotOf(t, `{"datasets":[{"name":" Raw ","upstreams":[]},{"name":"RAW","upstreams":[]}]}`)
514		report := CompareSnapshots(oldSnap, newSnap)
515		want := []RootSourceChange{{Dataset: "RAW", OldRoots: []string{" Raw "}, NewRoots: []string{"RAW"}}}
516		if !reflect.DeepEqual(report.RootSourceChanges, want) {
517			t.Errorf("RootSourceChanges = %#v, want %#v", report.RootSourceChanges, want)
518		}
519	}
520	
