522		t.Helper()
523		if len(report.NewDatasets) != 0 || len(report.RemovedDatasets) != 0 || len(report.ChangedDatasets) != 0 ||
524			len(report.AddedRelations) != 0 || len(report.RemovedRelations) != 0 || len(report.RootSourceChanges) != 0 {
