400	// dupFieldSnapshot produces a snapshot of graphJSON whose bytes then have one
401	// known field declared a second time, so the document is ambiguous even
402	// though the surviving values still describe the same graph.
403	func dupFieldSnapshot(t *testing.T, graphJSON string) (path string, content string) {
404		t.Helper()
405		target := filepath.Join(t.TempDir(), "snap.json")
406		if _, stderr, exit := snapshotViaCLI(t, graphJSON, target); exit != 0 {
407			t.Fatalf("seed snapshot: %s", stderr)
408		}
409		valid := readFile(t, target)
410		// Drop the lock file left by the seeding save so callers can assert that
411		// compare/trace create no lock of their own.
412		if err := os.Remove(target + ".lock"); err != nil {
413			t.Fatalf("remove seed lock: %v", err)
414		}
415		// Declare formatVersion twice: first 2, then the valid 1. The reader would
416		// silently keep the 1 and every other check would pass.
417		dup := strings.Replace(valid, `"formatVersion": 1`, `"formatVersion": 2, "formatVersion": 1`, 1)
418		if dup == valid {
419			t.Fatalf("could not inject duplicate field into %s", valid)
420		}
421		return target, dup
422	}
