	}
	infoAfter, _ := os.Stat(target)
	if !infoAfter.ModTime().Equal(infoBefore.ModTime()) {
		t.Errorf("refusal rewrote the target: mtime %s -> %s", infoBefore.ModTime(), infoAfter.ModTime())
	}
}

